import React from 'react';
import ReactDOM from 'react-dom';
import { Tree } from '@alifd/next';

const { Node: TreeNode } = Tree;

class ControlledTreeToggleDemo extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      selectedKey: null
    };
    this.handleSelect = this.handleSelect.bind(this);
  }

  handleSelect(selectedKeys, extra) {
    console.log('onSelect - keys:', selectedKeys, 'extra.selected:', extra.selected);
    // 点击时如果 extra.selected 为 true，保存当前 key，否则清空
    if (extra.selected) {
      this.setState({ selectedKey: selectedKeys[0] });
    } else {
      this.setState({ selectedKey: null });
    }
  }

  render() {
    const { selectedKey } = this.state;
    // 将 state 转换为受控的 selectedKeys 数组
    const selKeys = selectedKey ? [selectedKey] : [];
    return (
      <Tree
        selectable
        selectedKeys={selKeys}
        onSelect={this.handleSelect}
        style={{ width: 240, margin: 20 }}
      >
        <TreeNode label="Node 1" key="1">
          <TreeNode label="Child 1-1" key="1-1" />
          <TreeNode label="Child 1-2" key="1-2" />
        </TreeNode>
        <TreeNode label="Node 2" key="2" />
      </Tree>
    );
  }
}

ReactDOM.render(<ControlledTreeToggleDemo />, mountNode);
